export const verifyPattern = new RegExp("(?:^|[\\s;&|(])(?:(?:~?/)?(?:[\\p{L}\\p{N}_.\\-]+/)*python\\p{Nd}?(?:\\.\\p{Nd}+)?\\s+)?(?:~?/)?(?:[\\p{L}\\p{N}_.\\-]+/)*(?:pytest|py\\.test|tox|nox|python\\p{Nd}?(?:\\.\\p{Nd}+)?\\s+-m\\s+(?:pytest|unittest)|manage\\.py\\s+test|runtests(?:\\.py)?|jest|vitest|mocha|ava|playwright\\s+test|(?:npm|pnpm|yarn|bun)\\s+(?:run\\s+)?test|go\\s+test|cargo\\s+(?:test|nextest)|(?:mvn|mvnw|\\./mvnw)\\s+(?:\\S+\\s+)*test|(?:gradle|gradlew|\\./gradlew)\\s+(?:\\S+\\s+)*test|make\\s+(?:test|check)|ctest|rspec|rake(?:\\s+\\w+=\\S*)*\\s+(?:test|spec)(?::[\\w:]+)?|rails\\s+test(?::[\\w:]+)?|phpunit|dotnet\\s+test|swift\\s+test|mix\\s+test|deno\\s+test|node\\s+--test|bazel\\s+test|(?:\\./)?bin/test)(?![\\p{L}\\p{N}_.\\-/])","ui");
export const notRunPattern = new RegExp("\\s(?:-h|--help|--version|--collect-only|--co|--list\\S*)(?!\\S)","u");
export const prefixPattern = new RegExp("^\\s*(?:(?:[\\p{L}\\p{N}_]+=\\S*|time|nohup|command|nice(?:\\s+(?:-n\\s*|--adjustment=)?[-+]?\\d+)?|env(?:\\s+(?:(?:-[uC]|--unset|--chdir)(?:=|\\s*)[^\\s-]\\S*|-[-\\w]*))*|timeout(?:\\s+(?:-\\S+|[A-Z]+|\\p{Nd}\\S*))+|(?:(?:uv|poetry|pipenv|pdm|hatch|rye)\\s+run|npx|bunx|(?:npm|pnpm|yarn)\\s+(?:exec|dlx)|bundle\\s+exec|xvfb-run)(?:\\s+-\\S+)*|dotenv(?:\\s+(?!--(?:\\s|$))\\S+)*\\s+--)\\s+)*","u");
export const reportPattern = new RegExp("^\\s*(?:echo|printf|true|:|exit)(?:\\s|$)","u");
export const runFailedPattern = new RegExp("\\b[1-9]\\p{Nd}* (?:failed|errors?)\\b.*\\bin \\p{Nd}+(?:\\.\\p{Nd}+)?s\\b|^FAILED \\((?:failures|errors)=|^tests finished:.*\\b[1-9]\\p{Nd}* (?:failed|exceptions?)\\b|^# fail [1-9]|^Tests:.*\\b[1-9]\\p{Nd}* failed\\b|^\\s*Tests\\s+[1-9]\\p{Nd}* failed\\b|^\\s*[1-9]\\p{Nd}* failing\\b|^\\s*[1-9]\\p{Nd}* failed\\s*$|^(?:--- FAIL: |FAIL\\t|FAIL$)|^test result: FAILED|\\b\\p{Nd}+ examples?, [1-9]\\p{Nd}* failures?\\b|Tests run: \\p{Nd}+, Failures: (?:[1-9]|0, Errors: [1-9])|BUILD FAIL(?:URE|ED)|^\\d+ (?:runs|tests), \\d+ assertions, (?:[1-9]\\d* failures, \\d+ errors|\\d+ failures, [1-9]\\d* errors)\\b","um");
export const runPassedPattern = new RegExp("\\b\\p{Nd}+ passed\\b.*\\bin \\p{Nd}+(?:\\.\\p{Nd}+)?s\\b|^OK(?: \\(.*\\))?\\s*$|^tests finished: \\p{Nd}+ passed|^# fail 0\\b|^Tests:\\s+\\p{Nd}+ passed|^\\s*Tests\\s+\\p{Nd}+ passed|^\\s*\\p{Nd}+ passing\\b|^\\s*\\p{Nd}+ passed \\(\\p{Nd}+(?:\\.\\p{Nd}+)?(?:ms|s|m|h)\\)|^ok\\s+\\S+\\s+(?:\\p{Nd}+(?:\\.\\p{Nd}+)?s|\\(cached\\))|^test result: ok\\.|\\b\\p{Nd}+ examples?, 0 failures\\b|BUILD SUCCESS|^\\d+ (?:runs|tests), \\d+ assertions, 0 failures, 0 errors\\b","um");

// Ruby options are case-sensitive: -W must not admit the syntax-only -wc.
export const rubyVerifyPattern = /^(?:~?\/)?(?:[\w.\-]+\/)*ruby(?:\s+(?:-[Ir](?:\S+|\s+[^\s\-]\S*)|-C\s*\S+|-W[0-2]?(?::\S+)?|--[\w\-]+(?:=\S+)?|-[abdf-zABDF-Z]+))*\s+(?:[\w.\-~]*\/)*(?:test_[\w.\-]*|[\w.\-]*_(?:test|spec))\.rb(?![\w.\-/])/u;
